create extension if not exists pgcrypto;
create type public.member_role as enum ('owner','admin','sales','viewer');
create type public.document_type as enum ('quote','purchase_order');
create type public.document_status as enum ('draft','awaiting_confirmation','confirmed','generated','sent','cancelled');
create table public.organizations(id uuid primary key default gen_random_uuid(),name text not null,legal_name text,tax_id text,phone text,address jsonb not null default '{}',logo_path text,brand jsonb not null default '{}',created_at timestamptz not null default now(),deleted_at timestamptz);
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text not null,phone text unique,created_at timestamptz not null default now());
create table public.organization_members(organization_id uuid not null references public.organizations(id),user_id uuid not null references public.profiles(id),role public.member_role not null default 'sales',created_at timestamptz not null default now(),primary key(organization_id,user_id));
create table public.customers(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),name text not null,tax_id text,email text,phone text,address jsonb not null default '{}',created_at timestamptz not null default now(),deleted_at timestamptz);
create table public.suppliers(like public.customers including defaults including constraints);
alter table public.suppliers add primary key(id); alter table public.suppliers add foreign key(organization_id) references public.organizations(id);
create table public.catalog_items(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),kind text not null check(kind in('product','service')),name text not null,description text,unit text not null default 'un',unit_price numeric(14,2) not null default 0,active boolean not null default true,created_at timestamptz not null default now(),deleted_at timestamptz);
create table public.document_sequences(organization_id uuid not null references public.organizations(id),type public.document_type not null,year integer not null,next_value bigint not null default 1,primary key(organization_id,type,year));
create table public.documents(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),type public.document_type not null,number text not null,status public.document_status not null default 'draft',customer_id uuid references public.customers(id),supplier_id uuid references public.suppliers(id),counterparty_snapshot jsonb not null,subtotal numeric(14,2) not null default 0,discount numeric(14,2) not null default 0,shipping numeric(14,2) not null default 0,total numeric(14,2) not null default 0,commercial_terms jsonb not null default '{}',notes text,confirmed_at timestamptz,confirmed_by uuid references public.profiles(id),issued_by uuid not null references public.profiles(id),validation_code uuid not null default gen_random_uuid(),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz,unique(organization_id,number),check((type='quote' and customer_id is not null) or (type='purchase_order' and supplier_id is not null)));
create table public.document_items(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),document_id uuid not null references public.documents(id) on delete cascade,catalog_item_id uuid references public.catalog_items(id),position integer not null,description text not null,quantity numeric(14,4) not null check(quantity>0),unit text not null,unit_price numeric(14,2) not null check(unit_price>=0),discount numeric(14,2) not null default 0,line_total numeric(14,2) not null,unique(document_id,position));
create table public.conversations(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),user_id uuid references public.profiles(id),whatsapp_contact_id text not null,state text not null default 'menu',context jsonb not null default '{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.messages(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),conversation_id uuid not null references public.conversations(id),whatsapp_message_id text not null unique,direction text not null check(direction in('inbound','outbound')),kind text not null check(kind in('text','audio','document','interactive')),content jsonb not null default '{}',processing_status text not null default 'received',error_code text,created_at timestamptz not null default now());
create table public.files(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),document_id uuid references public.documents(id),storage_path text not null,mime_type text not null,size_bytes bigint not null check(size_bytes between 1 and 10485760),checksum text,created_at timestamptz not null default now(),deleted_at timestamptz);
create table public.document_events(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),document_id uuid not null references public.documents(id),event_type text not null,actor_id uuid references public.profiles(id),metadata jsonb not null default '{}',created_at timestamptz not null default now());
create table public.audit_logs(id bigint generated always as identity primary key,organization_id uuid not null references public.organizations(id),actor_id uuid references public.profiles(id),action text not null,entity_type text not null,entity_id uuid,metadata jsonb not null default '{}',created_at timestamptz not null default now());
create or replace function public.is_org_member(target uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.organization_members m where m.organization_id=target and m.user_id=auth.uid()) $$;
create or replace function public.has_org_role(target uuid,allowed public.member_role[]) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.organization_members m where m.organization_id=target and m.user_id=auth.uid() and m.role=any(allowed)) $$;
do $$ declare t text; begin foreach t in array array['organizations','profiles','organization_members','customers','suppliers','catalog_items','document_sequences','documents','document_items','conversations','messages','files','document_events','audit_logs'] loop execute format('alter table public.%I enable row level security',t); end loop; end $$;
create policy profiles_self_select on public.profiles for select using(id=auth.uid());
create policy profiles_self_insert on public.profiles for insert with check(id=auth.uid());
create policy profiles_self_update on public.profiles for update using(id=auth.uid()) with check(id=auth.uid());
create policy organizations_select on public.organizations for select using(public.is_org_member(id));
create policy organizations_insert on public.organizations for insert with check(auth.uid() is not null);
create policy organizations_update on public.organizations for update using(public.has_org_role(id,array['owner','admin']::public.member_role[])) with check(public.has_org_role(id,array['owner','admin']::public.member_role[]));
create policy members_select on public.organization_members for select using(public.is_org_member(organization_id));
create policy members_insert_first_owner on public.organization_members for insert with check(user_id=auth.uid() and role='owner' and not exists(select 1 from public.organization_members existing where existing.organization_id=organization_members.organization_id));
create policy members_manage on public.organization_members for all using(public.has_org_role(organization_id,array['owner','admin']::public.member_role[])) with check(public.has_org_role(organization_id,array['owner','admin']::public.member_role[]));
create policy sequences_select on public.document_sequences for select using(public.is_org_member(organization_id));
create policy sequences_write on public.document_sequences for all using(public.has_org_role(organization_id,array['owner','admin','sales']::public.member_role[])) with check(public.has_org_role(organization_id,array['owner','admin','sales']::public.member_role[]));
do $$ declare t text; begin foreach t in array array['customers','suppliers','catalog_items','documents','document_items','conversations','messages','files','document_events','audit_logs'] loop execute format('create policy %I on public.%I for select using(public.is_org_member(organization_id))',t||'_select',t); execute format('create policy %I on public.%I for insert with check(public.has_org_role(organization_id,array[''owner'',''admin'',''sales'']::public.member_role[]))',t||'_insert',t); execute format('create policy %I on public.%I for update using(public.has_org_role(organization_id,array[''owner'',''admin'',''sales'']::public.member_role[])) with check(public.has_org_role(organization_id,array[''owner'',''admin'',''sales'']::public.member_role[]))',t||'_update',t); end loop; end $$;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('organization-assets','organization-assets',false,5242880,array['image/png','image/jpeg','image/webp']),('documents','documents',false,10485760,array['application/pdf']) on conflict(id) do nothing;
create policy storage_org_read on storage.objects for select using(bucket_id in('organization-assets','documents') and public.is_org_member((storage.foldername(name))[1]::uuid));
create policy storage_org_write on storage.objects for insert with check(bucket_id in('organization-assets','documents') and public.has_org_role((storage.foldername(name))[1]::uuid,array['owner','admin','sales']::public.member_role[]));
